import{_ as t,o,c as a,ag as i}from"./chunks/framework.HG0H2VLS.js";const g=JSON.parse('{"title":"FilterBar — Figma Notes","description":"","frontmatter":{},"headers":[],"relativePath":"public/demos/src/patterns/FilterBar/FilterBar.figma-notes.md","filePath":"public/demos/src/patterns/FilterBar/FilterBar.figma-notes.md"}'),r={name:"public/demos/src/patterns/FilterBar/FilterBar.figma-notes.md"};function s(d,e,n,c,h,l){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="filterbar-—-figma-notes" tabindex="-1">FilterBar — Figma Notes <a class="header-anchor" href="#filterbar-—-figma-notes" aria-label="Permalink to &quot;FilterBar — Figma Notes&quot;">​</a></h1><h2 id="figma-node" tabindex="-1">Figma Node <a class="header-anchor" href="#figma-node" aria-label="Permalink to &quot;Figma Node&quot;">​</a></h2><ul><li><strong>File:</strong> <code>Lus07xi8pPXLN87sQIyrEt</code> (Affino AI Design System)</li><li><strong>Component set:</strong> <code>2977:3811</code> (&quot;Filters V2&quot;)</li><li><strong>Tier:</strong> <code>Pattern</code> → <code>src/patterns/FilterBar/</code></li><li>URL: <a href="https://www.figma.com/design/Lus07xi8pPXLN87sQIyrEt/Affino-AI---Design-System?node-id=2977-3811" target="_blank" rel="noreferrer">https://www.figma.com/design/Lus07xi8pPXLN87sQIyrEt/Affino-AI---Design-System?node-id=2977-3811</a></li></ul><p><strong>Two-row card:</strong> row 1 = saved-views + an explicit <strong>Export</strong> button + search/kebab; row 2 = the filter chips with &quot;Add Filters&quot; pinned right.</p><h2 id="characteristics" tabindex="-1">Characteristics <a class="header-anchor" href="#characteristics" aria-label="Permalink to &quot;Characteristics&quot;">​</a></h2><ul><li><strong>Two rows</strong> (border between): row 1 saved-views + Export + search/kebab, row 2 chips.</li><li><strong>Export</strong> is an explicit <code>btn--secondary</code> button in row 1.</li><li>Chips use the <strong>solid Default</strong> FilterItem treatment (only &quot;Add Filters&quot; is dashed), all <code>--rounded</code>.</li><li>Views trigger text is <strong>regular</strong> weight.</li><li><strong>Search mode</strong> replaces row 1 only — the chips row stays.</li><li><strong>Mobile:</strong> Export collapses out of the bar; chips wrap; search has icon+takeover or the Alt Search inline field.</li></ul><h2 id="variant-matrix-8-type-×-desktop-mobile-alt-search-mobile" tabindex="-1">Variant matrix (8 Type × Desktop/Mobile, + Alt Search mobile) <a class="header-anchor" href="#variant-matrix-8-type-×-desktop-mobile-alt-search-mobile" aria-label="Permalink to &quot;Variant matrix (8 Type × Desktop/Mobile, + Alt Search mobile)&quot;">​</a></h2><p><code>Type</code> = scenarios of one toolbar (modelled as JS modes + composed-component states).</p><table tabindex="0"><thead><tr><th>Node ID (Desktop / Mobile)</th><th>Type</th><th>Representation</th></tr></thead><tbody><tr><td>2977:3803 / 2977:3804</td><td>Default</td><td>base markup (solid chips)</td></tr><tr><td>2977:3801 / 2977:3810</td><td>Filter Active</td><td>a chip carries <code>.filter-item--selected</code></td></tr><tr><td>2977:3797 / 2977:3808</td><td>Views dropdown</td><td>saved-views <code>.dropdown</code> is <code>.is-open</code></td></tr><tr><td>2977:3799 / 2977:3806</td><td>New View</td><td>root <code>.filter-bar--new-view</code></td></tr><tr><td>2977:3798 / 2977:3802</td><td>Wrapping</td><td>more chips → row 2 flex-wraps</td></tr><tr><td>2989:6121 / 2989:6242</td><td>Save View</td><td>root <code>.filter-bar--save-view</code> reveals a &quot;Save view&quot; primary CTA (Button, sm) pinned right of row 2; Add Filters rejoins the chip flow</td></tr><tr><td>2977:3800 / 2977:3809</td><td>Search</td><td>root <code>.filter-bar--search</code></td></tr><tr><td>— / 2999:4699</td><td>Alt Search (mobile)</td><td>root <code>.filter-bar--alt-search</code> — <strong>mobile-only</strong> alternative to the search icon + takeover: a persistent search field fills row 1 between the views control and the kebab</td></tr><tr><td>2977:3807 / 2977:3805</td><td>Actions</td><td>kebab <code>.dropdown</code> is <code>.is-open</code></td></tr></tbody></table><p>Desktop fetched in full: Default, New View, Search. The rest are state/content permutations.</p><h2 id="layout" tabindex="-1">Layout <a class="header-anchor" href="#layout" aria-label="Permalink to &quot;Layout&quot;">​</a></h2><ul><li>Outer: <code>flex-direction: column</code>, <code>background: surface-primary</code>, border-secondary, radius-md. <strong>No <code>overflow: hidden</code></strong> — the root&#39;s own bg + radius round the card and the inter-row divider sits mid-card, so nothing needs clipping; clipping would crop the saved-views / kebab dropdown panels (which must escape the card).</li><li><strong>Row 1</strong> (<code>.filter-bar__row--top</code>, <code>border-bottom</code>): <code>[lead (views) .....16px..... [Export · Search · kebab]]</code>, px <code>--ai-spacing-5</code> / py <code>--ai-spacing-4</code>. <strong>Export, the search field, and the kebab are grouped in the <code>.filter-bar__actions</code> div</strong> (Figma row-1 &quot;Frame 230&quot;, e.g. 2989:6122) with an internal <code>--ai-spacing-3</code> (8px) gap; the row&#39;s <code>--ai-spacing-5</code> (16px) gap only separates the lead from that group. The <strong>search is a persistent 192px field</strong> (<code>--ai-size-3</code>) on desktop (Figma 2977:3803).</li><li><strong>Row 2</strong>: <code>[chips (flex-1, wrap) — &quot;Add Filters&quot; is the last chip in the flow]</code>, same padding. (In the Save View state a &quot;Save view&quot; CTA sits as a sibling after <code>__chips</code>, pinned right.)</li><li><strong>Search responsive behaviour:</strong> desktop shows the persistent <code>.filter-bar__search-bar</code> field + hides the search icon; <strong>mobile (≤767px)</strong> hides the field and shows the <strong>search icon</strong>, which enters the full-width <strong>takeover</strong> (<code>--search</code> mode → back-arrow + <code>.filter-bar__search</code> in lead). Implemented mobile-first: <code>.filter-bar__search-bar { display:none }</code>, then <code>@media (min-width:768px)</code> shows it (192px) and hides <code>.filter-bar__icon-btn[aria-label=&quot;Search&quot;]</code>.</li><li><strong>Mobile (≤767px):</strong> rows already stack; the <strong>Export button is hidden</strong> (<code>display:none</code>) per the Figma mobile variants; the <strong>chips row wraps</strong> to multiple lines (Figma mobile variant 2977:3804). The <strong>New View &quot;Create&quot; CTA uses the small button</strong> at mobile (<code>btn--sm</code> sizing applied to <code>.filter-bar__create</code> in the media query — padding <code>--ai-spacing-4</code>, <code>min-height --ai-spacing-7</code>, <code>font-size --ai-font-fluid-xxs</code>), per Figma mobile New View variant 2977:3806 (<code>button/sm</code>). Desktop keeps <code>button/base</code>.</li></ul><h2 id="modes-js-—-filterbar-js" tabindex="-1">Modes (JS — FilterBar.js) <a class="header-anchor" href="#modes-js-—-filterbar-js" aria-label="Permalink to &quot;Modes (JS — FilterBar.js)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mode</th><th>Class</th><th>Effect</th></tr></thead><tbody><tr><td>Search</td><td><code>.filter-bar--search</code></td><td>row 1 → back-arrow + full-width search Input (Export + actions hidden); <strong>chips row 2 stays</strong></td></tr><tr><td>New View</td><td><code>.filter-bar--new-view</code></td><td>row 1 views → &quot;New view&quot; Input + Create (Export + actions stay); <strong>row 2 collapses to just Add Filters</strong>. <strong>Create</strong> (<code>new-view-create</code>) appends the typed name to the saved-views list (<code>addView</code>, flagged <code>data-view-empty=&quot;1&quot;</code>) + selects it (<code>selectView</code>) + re-wires its … (<code>Dropdown.initAll</code>); <strong>×</strong> cancels. A new (empty) view shows <strong>only &quot;Add Filters&quot;</strong> via <code>.filter-bar--view-empty</code> (non-destructive — chips stay in the DOM). Existing views keep their default chips; <code>selectView</code> toggles <code>--view-empty</code> from the row&#39;s flag, so switching back restores them.</td></tr><tr><td>Alt Search</td><td><code>.filter-bar--alt-search</code></td><td><strong>mobile-only</strong> alternative search treatment (Figma 2999:4699). Instead of the search icon + full-width takeover, the persistent <code>.filter-bar__search-bar</code> field is shown and <strong>fills</strong> row 1 (<code>flex:1</code>) between the views control and the kebab. The views trigger becomes a <strong>plain borderless control</strong> (<code>width:auto</code>, no border / bg / padding — not the 192px field) so the search gets the width; row-1 gap is <code>--ai-spacing-5</code> (16px) between the views control and the search field. Search icon hidden. Desktop unchanged. CSS-only (modifier on the root).</td></tr><tr><td>Save View</td><td><code>.filter-bar--save-view</code></td><td>a filter added/amended — <strong>mock</strong>: clicking the &quot;Add Filters&quot; chip (FilterItem bubbles <code>filter-item:toggle</code> with <code>open:true</code>) reveals the <code>.filter-bar__save</code> &quot;Save view&quot; CTA (Button <code>--primary --sm</code>) — the last child <strong>inside</strong> <code>__chips</code>, after &quot;Add Filters&quot;. <strong>Desktop:</strong> <code>margin-left:auto</code> pins it to the right edge of the chip row. <strong>Mobile (≤767px):</strong> that margin is dropped so it flows right after &quot;Add Filters&quot; in the wrapping chips (Figma mobile 2989:6242). Clicking the CTA (<code>data-filter-action=&quot;save-view&quot;</code>) is a mock &quot;save&quot; — drops the class + closes the Add Filters chip. <strong>TODO(backend:Filters)</strong> — real trigger is a persisted filter-set change.</td></tr></tbody></table><p><strong>Saved-view selection + rename</strong> (<code>FilterBar.js</code> <code>wireViews</code> —: double-click OR the <strong>&quot;Rename&quot; item in the row&#39;s … menu</strong> (<code>[data-filter-rename]</code>, beside Copy/Delete) runs an inline <code>.filter-bar__rename</code> overlay; capture-phase click takeover + 220ms single/double disambiguation; the … is on every row incl. the selected one and is always-visible on touch via <code>@media (hover: none)</code> in <code>Dropdown.css</code>; code-first, not in Figma — flag for designer) and the <strong>right-aligned kebab panel</strong> (<code>.filter-bar__menu .dropdown__panel { left:auto; right:0 }</code>). The search field lives inside <code>__lead</code> (which stays visible in search mode), so it needs no relocation.</p><h2 id="css-class-mapping" tabindex="-1">CSS Class Mapping <a class="header-anchor" href="#css-class-mapping" aria-label="Permalink to &quot;CSS Class Mapping&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Element</th><th>Class</th><th>Notes</th></tr></thead><tbody><tr><td>Root</td><td><code>.filter-bar</code></td><td>column, border-secondary, radius-md, overflow hidden</td></tr><tr><td>Row</td><td><code>.filter-bar__row</code> (+<code>--top</code>)</td><td>flex, gap 16, pad 12/16 (12 all sides at mobile); <code>--top</code> adds bottom border</td></tr><tr><td>Lead (row 1)</td><td><code>.filter-bar__lead</code></td><td>flex-1, gap 8 — holds views / new-view / search</td></tr><tr><td>Views control</td><td><code>.dropdown.filter-bar__views</code></td><td>Dropdown filter-views panel; trigger field is <strong>regular</strong> weight</td></tr><tr><td>Actions</td><td><code>.filter-bar__actions</code></td><td>row-1 group (Figma &quot;Frame 230&quot;), 8px gap: <strong>Export</strong> + persistent search field (desktop) / search icon-btn (mobile) + kebab <code>.dropdown</code></td></tr><tr><td>Export</td><td><code>.btn.btn--secondary.filter-bar__export</code></td><td>first child of <code>.filter-bar__actions</code>; Button + <code>download</code> icon; hidden on mobile</td></tr><tr><td>Search field (desktop)</td><td><code>.input.filter-bar__search-bar</code></td><td>persistent 192px Input; desktop only — replaced by the icon + takeover on mobile</td></tr><tr><td>Chips (row 2)</td><td><code>.filter-bar__chips</code></td><td>flex-wrap, gap 6 (<code>--ai-spacing-2</code>, all sizes); chips are FilterItem <strong>default (solid)</strong> / <code>--selected</code>, <strong>all <code>--rounded</code></strong> (pill <code>--ai-radius-full</code>, per user direction)</td></tr><tr><td>Add Filters</td><td><code>.filter-item--empty.filter-item--rounded.filter-bar__add</code></td><td>dashed pill; <strong>last chip inside <code>__chips</code></strong> (in the flow, after the filter list)</td></tr><tr><td>Save view CTA</td><td><code>.btn.btn--primary.btn--sm.filter-bar__save</code></td><td>composes Button (primary, sm); hidden until <code>.filter-bar--save-view</code>, then pinned right of row 2</td></tr><tr><td>Search / New-view / Create / Back</td><td><code>.filter-bar__{search,new-view,create,back}</code></td><td>compose Input / Button</td></tr></tbody></table><h2 id="token-mapping" tabindex="-1">Token Mapping <a class="header-anchor" href="#token-mapping" aria-label="Permalink to &quot;Token Mapping&quot;">​</a></h2><p>Token set: surface-primary, border-secondary, spacing-3/4/5/8, size-3, radius-md, icon-contrast, icon-size-sm, font-body/fixed-xs/leading-md). The views trigger uses <code>--ai-font-regular</code>. Export button uses the Button component&#39;s <code>--ai-btn-secondary-*</code> tokens. Selected chips use <code>--ai-surface-info-soft</code> / <code>--ai-border-info</code> via the FilterItem component.</p><h2 id="token-gaps" tabindex="-1">Token Gaps <a class="header-anchor" href="#token-gaps" aria-label="Permalink to &quot;Token Gaps&quot;">​</a></h2><p>None for the shell. Documented Figma artifact: the &quot;Add Filters&quot; <strong>MinimalBadge</strong> uses raw <code>#364153</code> (Gray/700) — replaced here with a proper <strong>FilterItem <code>--empty</code></strong> (<code>--ai-text-primary</code>). Outer frame width is <code>970px</code> in Figma (no token) — built <strong>fluid</strong> (<code>width: 100%</code>, consumer-controlled), so the arbitrary 970 is not hardcoded.</p><h2 id="responsive-—-container-queries-not-viewport-changed-2026-09-17" tabindex="-1">Responsive — container queries, not viewport (changed 2026-09-17) <a class="header-anchor" href="#responsive-—-container-queries-not-viewport-changed-2026-09-17" aria-label="Permalink to &quot;Responsive — container queries, not viewport (changed 2026-09-17)&quot;">​</a></h2><p>The Device=Mobile treatment (Export collapses out of the bar, the search field becomes an icon) keys on <strong><code>@container cs-page</code></strong>, not <code>@media</code>. <code>cs-page</code> is ControlScreen&#39;s <code>.cc-control__page</code> — the content column.</p><p>This was a real bug, not a tidy-up. With the SidebarMenu docked, a <strong>954px viewport</strong> leaves the content column at <strong>562px</strong>: the datatable collapsed correctly (it already used container queries) but the FilterBar kept its widest layout, because 954 &gt; 767. Two failures compounded:</p><ol><li><strong>Wrong query type.</strong> Export and the 192px search field stayed visible in a column that could not hold them.</li><li><strong>An intrinsic floor.</strong> <code>.filter-bar__lead</code> is <code>flex: 1 0 0; min-width: 0</code>, so its box may shrink below its content — but <code>.filter-bar__views-trigger</code> carried a hard <code>width: 192px</code>. The trigger escaped its parent&#39;s box and painted <strong>over</strong> the Export button (measured: lead box ended at 499.5, the trigger ran to 569, Export started at 515.5).</li></ol><p>Both are fixed. Fixed widths on the views control, the search field and the new-view field are now <strong>caps, not floors</strong> (<code>flex: 0 1 &lt;size&gt;</code> + <code>max-inline-size</code> + <code>min-inline-size: 0</code>), so the bar degrades gracefully in the band above the breakpoint too.</p><p><strong>The cap sits on <code>.filter-bar__views</code>, never on the trigger.</strong> <code>.filter-bar__views</code> is also a <code>.dropdown</code>, which is <code>flex-direction: column</code> — putting <code>flex: 0 1 192px</code> on the trigger sized its <strong>block</strong> axis and drew a 192×192 square. Same trap applies to <code>.input</code> (also a column): <code>.filter-bar__search-bar</code> and <code>.filter-bar__new-view</code> are safe because they <em>are</em> the <code>.input</code> element and are themselves row items.</p><p><code>@media (hover: none)</code> is untouched — that is a device capability, not a size.</p><p><strong>The standalone demo establishes <code>cs-page</code> on <code>body</code>.</strong> Without it none of the narrow rules could ever fire and the demo would silently misrepresent the component (CLAUDE.md §4a). The device-toggle&#39;s 384px iframe works because that iframe&#39;s own body establishes the container.</p><p>Verified with no overlap and no table overflow at viewport widths 1700, 1400, 1200, 1024, 954, 860, 800, 700, 600, 500 and 390, plus the demo&#39;s 384px embed.</p><h2 id="overflow-kebab-actions-menu-—-size-xs-leading-icons" tabindex="-1">Overflow (kebab) actions menu — Size=xs + leading icons <a class="header-anchor" href="#overflow-kebab-actions-menu-—-size-xs-leading-icons" aria-label="Permalink to &quot;Overflow (kebab) actions menu — Size=xs + leading icons&quot;">​</a></h2><p>Built to Figma&#39;s &quot;Actions Menu&quot; screen on the Listings page (<code>3645:157810</code> desktop, list frame <code>3645:158885</code>, rows <code>3645:158886/158887</code>). Corrected 2026-09-17; it had been base-size with no icons.</p><table tabindex="0"><thead><tr><th>Property</th><th>Figma</th><th>Built as</th></tr></thead><tbody><tr><td>Row height</td><td>36px</td><td><strong>32px</strong> — <code>dropdown-item--xs</code></td></tr><tr><td>Padding</td><td><code>py --ai-spacing-2</code> / <code>px --ai-spacing-4</code></td><td><code>--ai-spacing-1</code> / <code>--ai-spacing-3</code></td></tr><tr><td>Label</td><td><code>--ai-font-fixed-xs</code> (14px), regular</td><td><code>--ai-font-fixed-2xs</code> (13px), medium</td></tr><tr><td>Leading icon</td><td>16px</td><td>12px (<code>--ai-icon-size-xs</code>)</td></tr><tr><td>Panel</td><td><code>p --ai-spacing-3</code> (8px), <code>--ai-radius-md</code>, <code>--ai-border-secondary</code>, drop-shadow</td><td>as Figma, scoped — see below</td></tr></tbody></table><p><strong>Size=xs is a deliberate divergence from Figma</strong> (designer, 2026-09-17: &quot;make them xs on the dropdown__panel&quot;). Figma draws these rows at 36px, i.e. <code>dropdown-item--sm</code>, and that is what was built first. Note xs is not simply a shorter row — it changes four properties at once (both padding axes, 14px regular → 13px medium, 16px icon → 12px), which is why the table above lists Figma and built values separately rather than as a single spec.</p><p>The <strong>saved-views menu in the same bar stays <code>--sm</code></strong>, which is what Figma gives it — so the two menus in this component are now deliberately different sizes. The chrome&#39;s menus (Zone Selector, User Menu) are <code>40px</code> base per Figma and were left alone.</p><p>Icons are Lucide <strong><code>sheet</code></strong> and <strong><code>file-spreadsheet</code></strong>. Note the Figma layers are both <em>named</em> <code>Icon/24px/Star</code> — stale layer names; the exported assets are the two above, so go by the asset, not the layer name.</p><p><strong>The panel padding is scoped to this menu.</strong> Figma&#39;s list frame binds <code>--ai-spacing-3</code> (8px) where the shared <code>.dropdown__panel</code> uses <code>--ai-spacing-4</code> (12px), so <code>.filter-bar__menu .dropdown__panel</code> overrides it rather than changing the panel every other dropdown uses.</p><p>It was load-bearing at Size=sm: a 16px icon plus a <code>data-text</code> reserve measured at the <strong>bold</strong> weight left &quot;Generate Shipping Labels&quot; 168px against the ~172px it needed, so it wrapped and the row measured 60px instead of 36px. At Size=xs (13px text, 12px icon) it clears at either padding — the 8px is kept because it matches Figma, not because it is still holding the layout up.</p><h2 id="ghost-buttons-in-the-saved-views-menu-2026-09-17" tabindex="-1">Ghost buttons in the saved-views menu (2026-09-17) <a class="header-anchor" href="#ghost-buttons-in-the-saved-views-menu-2026-09-17" aria-label="Permalink to &quot;Ghost buttons in the saved-views menu (2026-09-17)&quot;">​</a></h2><p>The row menu (Rename / Copy / Delete) and the &quot;New view&quot; footer are <code>btn btn--tertiary btn--sm</code>, and every one of them rendered as a <strong>permanent grey pill</strong>. Designer: &quot;none of the buttons in the view dropdown should have a bg by default, they should only be visible on mouseover.&quot;</p><p>The cause is not the FilterBar. In the <strong>CC theme</strong> the tertiary ladder runs backwards:</p><table tabindex="0"><thead><tr><th>Token</th><th>Base theme</th><th>CC theme</th></tr></thead><tbody><tr><td><code>--ai-btn-tertiary-bg</code> (rest)</td><td><code>transparent</code></td><td><strong>#e7edf0</strong> — visible</td></tr><tr><td><code>--ai-btn-tertiary-bg-hover</code></td><td>#f8fafc</td><td><strong>#f2f4f5</strong> — <em>lighter than rest</em></td></tr></tbody></table><p>So in CC a tertiary button is filled at rest and gets <strong>lighter</strong> on hover. Outside CC it behaves as the ghost button it is meant to be.</p><p>Fixed by scoping <code>.filter-bar__views .btn--tertiary</code> to transparent, with <code>--ai-surface-secondary</code> on hover — the same <code>#e7edf0</code> the buttons were showing at rest, and the same value <code>.dropdown-item:hover</code> uses in the panel directly above. <strong>The grey is not removed, it is moved to where it belongs.</strong><code>:focus-visible</code> is aligned to hover on purpose: left alone it inherits the lighter hover token, so a keyboard user would get a weaker highlight than a mouse user on the same control.</p><p><strong>This is the fourth independent workaround for the same token bug.</strong><code>Header.css</code> forces <code>.cc-header .btn--tertiary</code> transparent, and <code>AiAssistant.css</code> does it for two more selector groups — restoring the grey on hover with <code>var(--ai-btn-tertiary-bg)</code>, the same move arrived at separately. Four components patching one token says the token is wrong, not the components.</p><p><strong>The real fix is in Figma</strong>: give <code>--ai-btn-tertiary-bg</code> the transparent value in CC that it already has in the base theme, and let hover carry the grey. That makes all four blocks redundant — delete them when it lands.</p><h2 id="row-menus-collapse-with-the-panel-2026-09-17" tabindex="-1">Row menus collapse with the panel (2026-09-17) <a class="header-anchor" href="#row-menus-collapse-with-the-panel-2026-09-17" aria-label="Permalink to &quot;Row menus collapse with the panel (2026-09-17)&quot;">​</a></h2><p>A saved-view row&#39;s … menu (Rename / Copy / Delete) stayed open when the panel around it closed, so re-opening the saved-views dropdown showed the menu still hanging off a row the user may not have been acting on.</p><p>Every row menu is now collapsed whenever the panel loses <code>is-open</code>, watched with a <strong>MutationObserver on the panel&#39;s class attribute</strong> rather than by calling a close helper from each exit.</p><p>That choice is deliberate: there are <strong>five</strong> ways this panel closes, and <code>FilterBar.js</code> owns only two of them (<code>closeDropdowns()</code> and <code>selectView()</code>). The other three — trigger toggle, outside click and Escape — belong to <code>Dropdown.js</code>, which emits <strong>no close event</strong>; it only removes the class. So hooking the class is the single place that catches all five without reaching into the shared Dropdown component.</p><p>Verified against all five paths by driving real clicks and key events, and by re-running with the observer removed to confirm the test actually fails without it (Escape and trigger-toggle both leave the menu open, and the stale state then corrupts the next interaction).</p><p>One gotcha for anyone testing this: selecting a row runs through a <strong>220ms</strong> timer that separates single-click-select from double-click-rename, so a test that waits less than that will see the panel still open and wrongly conclude the path is broken.</p><h2 id="export-is-a-split-control-2026-09-17" tabindex="-1">Export is a split control (2026-09-17) <a class="header-anchor" href="#export-is-a-split-control-2026-09-17" aria-label="Permalink to &quot;Export is a split control (2026-09-17)&quot;">​</a></h2><p>Export was a single <code>btn btn--secondary</code>. It is now the same split control the Seating Planner toolbar uses (designer: &quot;use the same style as we did for the seating planner&quot;) — the label half runs the default export, the chevron half opens a format menu of <strong>PDF / Excel (.xlsx) / CSV</strong>.</p><p><strong>Figma formalised the look, not the behaviour.</strong> On the same day the designer added a Button Type <code>Secondary / Action</code> — base <code>3679:17496</code>, sm <code>3679:99941</code> — a <em>single</em> button with a full-height divider before a trailing icon, and supplied it as a <strong>visual reference only</strong>. The behaviour built here is the split control, which one button cannot provide: it needs two separate targets.</p><p>The new Type&#39;s spec, recorded because it is what the look traces to:</p><table tabindex="0"><thead><tr><th></th><th>base <code>3679:17496</code></th><th>sm <code>3679:99941</code></th></tr></thead><tbody><tr><td>height</td><td><code>--ai-spacing-8</code> (40)</td><td><code>--ai-spacing-7</code> (32)</td></tr><tr><td>gap</td><td><code>--ai-spacing-4</code> (12)</td><td><code>--ai-spacing-3</code> (8)</td></tr><tr><td>padding-inline</td><td><code>--ai-spacing-4</code> (12)</td><td><code>--ai-spacing-4</code> (12)</td></tr><tr><td>text</td><td><code>--ai-font-fluid-xs</code> (14)</td><td><code>--ai-font-fluid-xxs</code> (12)</td></tr></tbody></table><p>Both are <code>--ai-btn-secondary-bg</code> / <code>--ai-btn-secondary-border</code> / <code>--ai-radius-md</code> with a 16px trailing icon. Base and sm were fetched separately and <strong>do differ beyond size</strong> — the gap steps 12 → 8, which reading the base node alone would have missed.</p><p><strong>The divider is not an element.</strong> It is the shared border: the halves are pulled together by <code>-1px</code> so two adjacent 1px borders collapse into the single rule Figma draws instead of stacking to 2px. The hovered/focused half is lifted with <code>z-index: 1</code> so it paints its whole outline including that collapsed edge.</p><h3 id="open-on-the-figma-side" tabindex="-1">Open, on the Figma side <a class="header-anchor" href="#open-on-the-figma-side" aria-label="Permalink to &quot;Open, on the Figma side&quot;">​</a></h3><ul><li><strong>No interactive states.</strong> <code>Secondary / Action</code> exists only as <code>State=Default</code> at two sizes — no Hover / Focus / Pressed / Disabled, where plain Secondary has all five. The halves inherit <code>btn--secondary</code>&#39;s states here.</li><li><strong>The two variants disagree on the Type name</strong>: base is <code>Secondary / Action</code> (spaces), sm is <code>Secondary/Action</code> (none). In Figma those are two distinct Type values, so the axis currently reads as two types rather than one.</li><li><strong>The listing screens still draw a plain Export button</strong> with no divider, so the Listings page and the Button set now disagree.</li></ul><h3 id="resolved-the-split-is-btn-group-2026-09-17" tabindex="-1">Resolved: the split is <code>.btn-group</code> (2026-09-17) <a class="header-anchor" href="#resolved-the-split-is-btn-group-2026-09-17" aria-label="Permalink to &quot;Resolved: the split is `.btn-group` (2026-09-17)&quot;">​</a></h3><p>The duplication flagged when this was built is gone. The split mechanics were never FilterBar&#39;s to own — <strong>ButtonGroup already had all three rules</strong>: the <code>-1px</code> collapsed edge, the first/last radius rounding, and the hover/focus <code>z-index</code>. Both this pattern and <code>SeatingPlanner.css</code> had hand-written their own copy before anyone checked whether a component existed.</p><p><code>.filter-bar__export-split</code> was deleted and the wrapper is now <code>.btn-group</code>. Geometry measured identical before and after. What remains here is only what is genuinely FilterBar&#39;s: the chevron half&#39;s <code>--ai-spacing-4</code> inline padding and the 160/8 panel sizing.</p><p><code>ButtonGroup.css</code> is now linked by this demo, ListingScreen and SeatingPlanner — none of the three loaded it before.</p><h2 id="chip-pickers-2026-09-17" tabindex="-1">Chip pickers (2026-09-17) <a class="header-anchor" href="#chip-pickers-2026-09-17" aria-label="Permalink to &quot;Chip pickers (2026-09-17)&quot;">​</a></h2><p>Clicking a chip opens the FilterDropdowns it is assigned. <code>FilterItem</code> emits <code>filter-item:toggle</code> and its contract says outright <em>&quot;Mount your own value picker on this event&quot;</em> — the bar is that consumer, so the mounting lives here.</p><p><strong>The bar stays generic.</strong> It never knows which dropdown Type a chip has, only that a chip <em>may</em> have a <code>.filter-bar__panel</code> sibling inside a <code>.filter-bar__chip</code> wrapper. The screen supplies the panel content, so one bar serves every listing screen. A chip with no panel simply no-ops — which is why this demo&#39;s 35 chips are unaffected.</p><p>Positioning is CSS, not measurement: the panel is a sibling inside a <code>position: relative</code> wrapper. The chips row <strong>wraps</strong>, so a JS-positioned panel would need recomputing on every reflow — and this column reflows with no window resize at all when the SidebarMenu docks. The one thing JS does measure is overflow: after showing, if the 320px card would overrun the bar&#39;s end edge it gets <code>.filter-bar__panel--end</code> to flip sides. That cannot be done before showing, since a hidden element has no box.</p><p><code>.filter-dropdowns</code> brings its own card chrome, so the wrapper adds none — nesting it in a <code>.dropdown__panel</code> would draw the border and shadow twice. Offset and layer match <code>.dropdown__panel</code> (<code>--ai-spacing-3</code>, z-index 10) so every popover in the bar sits on one convention.</p><h3 id="the-nested-chip-trap" tabindex="-1">The nested-chip trap <a class="header-anchor" href="#the-nested-chip-trap" aria-label="Permalink to &quot;The nested-chip trap&quot;">​</a></h3><p><strong>Type=More Filters is itself built from <code>.filter-item</code> chips</strong>, and those bubble <code>filter-item:toggle</code> exactly like a bar chip. Without a guard, clicking &quot;Order Date&quot; inside the Add Filters panel walks up to the Add Filters wrapper and closes the very panel it lives in. <code>panelOf()</code> returns null for any chip that is <code>.closest(&#39;.filter-bar__panel&#39;)</code>. Caught by testing the nested click, not by reading the code.</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>Composition: Dropdown-as-views-trigger, Input search, no invented hover/focus (WCAG <code>:focus-visible</code> only).</li><li>Export icon: Figma &quot;Icon/24px/Export&quot; (tray + down arrow) → Lucide <strong><code>download</code></strong>.</li></ul><h2 id="backend-handover" tabindex="-1">Backend handover <a class="header-anchor" href="#backend-handover" aria-label="Permalink to &quot;Backend handover&quot;">​</a></h2><p><code>TODO(backend:Filters)</code> — see <code>HANDOVER.md</code> → Surface: Filters (shared with FilterItem).</p><h2 id="dependencies" tabindex="-1">Dependencies <a class="header-anchor" href="#dependencies" aria-label="Permalink to &quot;Dependencies&quot;">​</a></h2><p>Dropdown (+ DropdownItem), FilterItem, Input, Button. Lucide: <code>chevron-down</code>, <code>download</code>, <code>search</code>, <code>ellipsis-vertical</code>, <code>arrow-left</code>, <code>plus</code>, <code>x</code>, <code>check</code>, <code>ellipsis</code>, <code>copy</code>, <code>trash-2</code>.</p><h2 id="chip-↔-picker-committing-a-selection" tabindex="-1">Chip ↔ picker: committing a selection <a class="header-anchor" href="#chip-↔-picker-committing-a-selection" aria-label="Permalink to &quot;Chip ↔ picker: committing a selection&quot;">​</a></h2><p>The bar joins two event contracts it does not own:</p><table tabindex="0"><thead><tr><th>Event</th><th>From</th><th>Meaning</th></tr></thead><tbody><tr><td><code>filter-dropdown-item:toggle</code></td><td>FilterDropdownItem</td><td>an option row was picked</td></tr><tr><td><code>filter-dropdowns:apply</code></td><td>FilterDropdowns</td><td>the panel&#39;s Apply was pressed</td></tr><tr><td><code>filter-item:clear</code></td><td>FilterItem</td><td>the chip&#39;s × was pressed</td></tr></tbody></table><p><code>valuesIn(panel)</code> reads the picked values <strong>from the panel&#39;s shape</strong>, never from a type name, so the bar stays generic and a new picker type needs no change here:</p><ol><li>a <code>[data-select-menu]</code> present → the selected option rows are the value. Predictive panels also contain a text input, but that is a SEARCH field — the menu must win, or a half-typed query would become the filter value.</li><li>checkboxes present → every checked label.</li><li>neither → a plain field, so its text is the value.</li></ol><p>The values go to <code>chip.setFilterValues()</code>, which is FilterItem&#39;s own API and already implements the Figma rollup (1–3 listed in full, 4+ → <code>&lt;first&gt;, and N more</code>) and the drop back to Default on an empty list. So the chip&#39;s selected state, its label and its separator all fall out of that one call — the bar computes none of them.</p><p><strong>Everything commits on Apply</strong> — every FilterDropdowns type but More Filters has the button (3039:5639). Picking an option row closes the MENU and fills the field; the chip changes only when Apply is pressed. Nothing in the bar listens to <code>filter-dropdown-item:toggle</code> for that reason.</p><p><strong>Gotcha — the option rows are a separate component.</strong> <code>FilterDropdowns.js</code> only CONSTRAINS <code>.filter-dropdown-item</code> to single-select; the click handler lives in <code>FilterDropdownItem.js</code>. A page that loads FilterDropdowns without it gets pickers that open and cannot be picked from, with no error. ListingScreen hit exactly this.</p><h2 id="adding-a-filter-to-the-bar" tabindex="-1">Adding a filter to the bar <a class="header-anchor" href="#adding-a-filter-to-the-bar" aria-label="Permalink to &quot;Adding a filter to the bar&quot;">​</a></h2><p>Clicking a facet in the More Filters panel emits <code>filter-bar:add-filter</code> (bubbles, <code>detail: { name }</code>). More Filters is the one type with no Apply, so the click IS the commit — and the panel stays OPEN: the facets are a pick-list several of which are usually wanted, and the picked one leaves the list as it goes. It closes on the outside click, like any panel.</p><p>That last part needs <code>composedPath()</code>, not <code>root.contains(e.target)</code>: the facet has been removed from the DOM by the time the document-level click listener runs, so the live-DOM check reports the click as OUTSIDE the bar and closes the panel the user is still picking from. The path is captured at dispatch and still remembers where the click came from.</p><p>The bar deliberately does <strong>not</strong> build the chip: it does not know what picker that filter wants. The screen owns the filter config, so it listens and splices the chip in before the Add Filters chip, then removes the facet from the panel.</p><p>Splice, not re-render: rebuilding the chip row would discard the selections already made on the other chips, which is the opposite of what adding a sixth filter should do.</p><h2 id="save-view-—-when-it-appears-and-what-it-does" tabindex="-1">Save view — when it appears, and what it does <a class="header-anchor" href="#save-view-—-when-it-appears-and-what-it-does" aria-label="Permalink to &quot;Save view — when it appears, and what it does&quot;">​</a></h2><p><code>.filter-bar--save-view</code> reveals the CTA. The state means <strong>the bar no longer matches the view it names</strong> — a difference, not &quot;a filter is set&quot;. A saved view full of filters is not dirty, and the CTA must vanish the moment its own view is saved, so &quot;any chip has values&quot; cannot be the test.</p><p>The comparison is a signature of the chips on the bar and the values each holds. Both halves matter: adding a filter changes the view before it has a value. Values come from <code>announce</code>, never from the chip&#39;s label, which rolls 4+ up into <code>&lt;first&gt;, and 3 more</code> and would call two different four-value selections identical. Reverting a change hides the CTA again, for free.</p><p><code>root.setViewExtra(string)</code> lets the CONSUMER put its own half of the view state into the same comparison. The listing uses it for the table layout: editing the columns is a change to the view in exactly the way adding a filter is, and has to reach the same CTA — but the bar has no business knowing what a column is, so the value is opaque and only ever compared.</p><p><code>root.resetSaveView(valuesByName)</code> re-baselines — the screen calls it after the first render, and after a view is selected or saved. It takes the values rather than trusting the bar&#39;s cache, because those chips are brand new.</p><p>This replaced a mock that revealed the CTA when the Add Filters chip was merely OPENED — a look that changes nothing was enough to offer a save.</p><h3 id="saving" tabindex="-1">Saving <a class="header-anchor" href="#saving" aria-label="Permalink to &quot;Saving&quot;">​</a></h3><p>The CTA does not save on the spot; a view needs a name, so it opens the naming field. That field is <strong>New View&#39;s</strong> (2977:3799) — the only naming UI Figma defines — under a second class, <code>--saving-view</code>, because New View also collapses row 2 to just Add Filters and a view being SAVED is being saved <em>because of</em> the chips on the bar. In that mode the Create button reads <strong>Save</strong> and the CTA that opened it is hidden (that last rule sits after <code>--save-view</code>&#39;s, since both are one class + one class and the cascade is decided by order).</p><p>Create then:</p><ol><li>marks the row non-empty, so selecting it keeps the chips;</li><li>dispatches <code>filter-bar:save-view</code> <code>{ name, view }</code> <strong>before</strong> selecting it — the screen snapshots its filter set against that row, and selecting would otherwise ask it to restore a view it has not recorded yet;</li><li>selects the row, which dispatches <code>filter-bar:select-view</code> <code>{ name, view }</code>.</li></ol><p>The bar owns the list and the rows; it never learns what a view MEANS. The screen keeps the snapshots, keyed by row element, and restores on select.</p><p>TODO(backend:Filters): saved views are in memory — a reload restores the shipped set.</p><h2 id="search" tabindex="-1">Search <a class="header-anchor" href="#search" aria-label="Permalink to &quot;Search&quot;">​</a></h2><p>Both search fields — the persistent desktop one and the mobile takeover — are the same search, so they mirror each other and either drives it.</p><p><code>filter-bar:search</code> (bubbles, <code>{ query }</code>) fires on input. The bar owns the <strong>3-character threshold</strong> and reports <code>&#39;&#39;</code> below it, so a consumer never has to re-check: one or two characters match most of a listing, and the table would thrash on the first keystroke then settle, which reads as a bug rather than a search. Typing within the threshold emits nothing at all.</p><p>Leaving the mobile takeover (<code>search-exit</code>) clears the query via <code>root.clearSearch()</code> — otherwise a field that is no longer on screen would keep filtering.</p><p>TODO(backend:Filters): the query belongs in the listing request, not in a client-side scan.</p><h2 id="one-thing-open-at-a-time" tabindex="-1">One thing open at a time <a class="header-anchor" href="#one-thing-open-at-a-time" aria-label="Permalink to &quot;One thing open at a time&quot;">​</a></h2><p>Every menu on the bar closes when a click lands anywhere else — including on another control WITHIN the bar. Two things were stopping that:</p><ol><li><strong>Dropdown&#39;s trigger called <code>stopPropagation()</code></strong>, so a click that opened one dropdown never reached <code>document</code> and no other dropdown heard it. Opening the kebab while the saved-views list was open left both on screen. It is safe to remove: each dropdown&#39;s own outside-click handler ignores clicks inside itself, so letting the event through cannot close the one being opened.</li><li><strong>The bar&#39;s chip-panel handler asked &quot;was this click inside the BAR?&quot;</strong> — so clicking the views control, the kebab, Export, the search field or bare space in the bar left an open picker hanging. It now asks &quot;was this click on a CHIP or inside its picker?&quot;, which is the question that actually matters.</li></ol><p>Verified as a chain — chip picker → views → kebab → Edit Columns → rows-per-page → bare bar space — with exactly one open at every step and none at the end. Clicking INSIDE an open picker still does not close it, and More Filters still stays open while facets are being picked.</p><h2 id="keeping-a-picker-inside-the-bar" tabindex="-1">Keeping a picker inside the bar <a class="header-anchor" href="#keeping-a-picker-inside-the-bar" aria-label="Permalink to &quot;Keeping a picker inside the bar&quot;">​</a></h2><p>Two steps, because neither alone is enough:</p><ol><li><strong>Flip</strong> to the end edge when the panel hangs off the right.</li><li><strong>Nudge</strong> whatever still sticks out, with a translate.</li></ol><p>The flip alone was fine while every picker was 320px. A panel anchors to its CHIP, though, and the chips wrap — so a wide one (More Filters runs to 640px) can hang off the LEFT even after flipping, simply because its chip sits mid-row. Measured at a 378px page: a 351px panel sat at left -56. Verified inside the bar at 430px, 900px and 1600px pages.</p><h2 id="discard-changes" tabindex="-1">Discard changes <a class="header-anchor" href="#discard-changes" aria-label="Permalink to &quot;Discard changes&quot;">​</a></h2><p>Sits beside Save view, shown and hidden by the same <code>--save-view</code> state — both appear exactly when the bar differs from the view it names.</p><p>It puts the bar back to that view. The capability already existed: re-picking the current view from the saved-views dropdown does precisely this. But it was buried behind a menu whose current row is already ticked, which does not look like an action, so nobody would find it.</p><p>Tertiary, next to the primary Save. Two things about the pair had to be fixed after the designer saw it (2026-09-18):</p><ul><li><strong>They are ONE flex item</strong>, wrapped in <code>.filter-bar__view-actions</code>. Left as siblings in the wrapping chip row they broke apart — Discard stayed on the chips line while Save view dropped to a line of its own, because each wraps independently and only one carried the auto-margin. Wrapped together they move together, and the margin belongs to the pair.</li><li><strong>Discard rendered as a solid grey pill</strong>, the CC tertiary token bug again. It is the FIFTH consumer of that one bug and the first outside a menu, where it read as a second competing button rather than the quiet option. Folded into the same scoped override as the saved-views buttons.</li></ul><p>Nothing is confirmed first: what is being discarded is visible on screen, and re-applying a filter is cheaper than a dialog.</p><p><code>filter-bar:discard-view</code> (bubbles, no detail). The bar does not know what the view held, so it only reports the intent; the screen restores its snapshot.</p><p>TODO(design:FilterBar): not in Figma — Type=Save View draws the one CTA.</p>',124)])])}const u=t(r,[["render",s]]);export{g as __pageData,u as default};
